const text = key => String($json[key] || '').trim();
const council = text('council').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const batch = text('batch');
const input_directory = text('input_directory').replace(/\/+$/, '');
if (!council) throw new Error('Council is required.');
if (!batch) throw new Error('A registered batch is required.');
if (!input_directory.startsWith('/data/') || input_directory.includes('/../') || input_directory.startsWith('/data/file-browser-data')) throw new Error('Input directory must be a safe path below /data and outside /data/file-browser-data.');
return [{json:{council,batch,input_directory,
  source_path:text('source_path'),
  capture_rules_paths:text('capture_rules_paths'),
  s3_inventory_paths:text('s3_inventory_paths'),
  portal_evidence_paths:text('portal_evidence_paths'),
  prior_findings: [], rework_round: 0}}];

const result = $json;
if (!result.coverage?.exact) throw new Error('Mapping completed without exact source/mapping/audit coverage.');
const form = $('Mapping job input').first().json;
const runReport = result.outputs?.run_report;
if (!runReport) throw new Error('Mapping run did not report an output directory.');
const runDirectory = runReport.replace(/\/[^/]+$/, '');
const positive = (value, fallback) => {
  const parsed = Number(String(value ?? '').trim());
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
};
return [{json:{
  status: result.status,
  // Carried forward because the loop's return path skips the request node,
  // so this is where a rework can read how deep it already is.
  rework_round: result.rework_round || 0,
  prior_findings: result.prior_findings || [],
  production_published: false,
  job_id: result.job_id,
  council: result.council,
  batch: result.batch,
  case_count: result.case_count,
  match_status_counts: result.match_status_counts,
  source_type_counts: result.source_type_counts,
  selected_capture_rules: result.selected_capture_rules,
  selected_s3_inventory: result.selected_s3_inventory,
  selected_portal_evidence: result.selected_portal_evidence,
  outputs: result.outputs,
  run_directory: runDirectory,
  // Everything the quality endpoint needs, assembled once so the working round
  // and the acceptance round cannot drift apart.
  quality_request: {
    council: result.council,
    batch: result.batch,
    run_directory: runDirectory,
    stage: 'working',
    sample_size: positive(form.sample_size, 12),
    budget_usd: positive(form.budget_usd, 3.0),
  },
}}];

const acceptance = $json;
const mapping = $('Mapping outputs').first().json;
const passed = acceptance.passed === true;
// The holdout is the only sample the spec was never tuned against, so it is the
// only one that may authorise publication.
return [{json:{
  status: passed ? 'accepted_on_holdout' : 'holdout_gate_failed',
  production_published: false,
  cleared_for_publication: passed,
  council: mapping.council,
  batch: mapping.batch,
  case_count: mapping.case_count,
  outputs: mapping.outputs,
  acceptance_metrics: acceptance.metrics,
  acceptance_reasons: acceptance.reasons || [],
  sampling_plan: acceptance.sampling_plan,
  budget: acceptance.budget,
  model: acceptance.model,
  quality_report: acceptance.quality_report,
}}];

// adjust_spec means the rule itself is wrong, which is the one gate outcome a
// recompile can answer. What the round saw goes back to the compiler as
// feedback instead of waiting for someone to resubmit the form and hope for a
// different spec. Stable inputs come from the request; loop state comes from
// the mapping step, which the return path does re-execute.
const review = $json;
const request = $('Validate mapping request').first().json;
const mapping = $('Mapping outputs').first().json;
const next = review.next || {};

const round = Number(mapping.rework_round || 0);
const finding = [];
if (next.detail) finding.push(String(next.detail));
for (const item of (next.focus || [])) finding.push(String(item));
for (const reason of (review.reasons || [])) finding.push(String(reason));
if (!finding.length) finding.push('A quality round rejected the mapping without naming a cause.');

return [{json:{
  council: request.council,
  batch: request.batch,
  input_directory: request.input_directory,
  source_path: request.source_path,
  capture_rules_paths: request.capture_rules_paths,
  s3_inventory_paths: request.s3_inventory_paths,
  portal_evidence_paths: request.portal_evidence_paths,
  rework_round: round + 1,
  prior_findings: [...(mapping.prior_findings || []), finding],
  status: 'quality_gate_failed_rule',
  action: next.action,
  detail: next.detail,
  focus: next.focus || [],
  round_index: review.round_index,
  metrics: review.metrics,
  coverage: review.coverage,
  quality_report: review.quality_report,
  production_published: false,
}}];

// investigate_cases means the failures are scattered, not a shared cause, so a
// recompile would fit the spec to two cases out of twelve. What resolves it is
// evidence: another round says whether those failures are noise or a systematic
// share the first sample was too small to separate. The spec is untouched.
const review = $json;
const mapping = $('Mapping outputs').first().json;
const next = review.next || {};
const plan = review.sampling_plan || {};
const rounds = Number(review.round_index || 0);

return [{json:{
  ...mapping,
  status: 'quality_gate_failed_cases',
  production_published: false,
  action: next.action,
  detail: next.detail,
  focus: next.focus || [],
  round_index: rounds,
  next_round_index: rounds + 1,
  sampled_ids: review.sampled_ids,
  metrics: review.metrics,
  coverage: review.coverage,
  working_pool_remaining: Math.max(0, (plan.working_cases || 0) - (review.sampled_ids || []).length),
  quality_report: review.quality_report,
}}];

const review = $json;
const next = review.next || {};
const plan = review.sampling_plan || {};
// The loop advances one round per submission: the state file remembers which
// cases each round drew, so resubmitting samples ground this batch has not seen.
return [{json:{
  status: "quality_gate_blocked_inputs",
  production_published: false,
  action: next.action,
  detail: next.detail,
  focus: next.focus || [],
  round_index: review.round_index,
  next_round_index: (review.round_index || 0) + 1,
  sampled_ids: review.sampled_ids,
  metrics: review.metrics,
  coverage: review.coverage,
  working_pool_remaining: Math.max(0, (plan.working_cases || 0) - (review.sampled_ids || []).length),
  quality_report: review.quality_report,
  guidance: "Every judged case failed for the same non-mapping reason, so the batch itself cannot be content-verified. Do not change the mapping spec; fix or replace the source evidence.",
}}];

const review = $json;
const next = review.next || {};
const plan = review.sampling_plan || {};
// The loop advances one round per submission: the state file remembers which
// cases each round drew, so resubmitting samples ground this batch has not seen.
return [{json:{
  status: "quality_pool_exhausted",
  production_published: false,
  action: next.action,
  detail: next.detail,
  focus: next.focus || [],
  round_index: review.round_index,
  next_round_index: (review.round_index || 0) + 1,
  sampled_ids: review.sampled_ids,
  metrics: review.metrics,
  coverage: review.coverage,
  working_pool_remaining: Math.max(0, (plan.working_cases || 0) - (review.sampled_ids || []).length),
  quality_report: review.quality_report,
  guidance: "Every working-pool case has been reviewed. Further rounds would resample ground already used to adjust the spec. Run the acceptance stage on the holdout, or widen the population.",
}}];

const review = $json;
const next = review.next || {};
const plan = review.sampling_plan || {};
// The loop advances one round per submission: the state file remembers which
// cases each round drew, so resubmitting samples ground this batch has not seen.
return [{json:{
  status: "quality_outcome_unrecognised",
  production_published: false,
  action: next.action,
  detail: next.detail,
  focus: next.focus || [],
  round_index: review.round_index,
  next_round_index: (review.round_index || 0) + 1,
  sampled_ids: review.sampled_ids,
  metrics: review.metrics,
  coverage: review.coverage,
  working_pool_remaining: Math.max(0, (plan.working_cases || 0) - (review.sampled_ids || []).length),
  quality_report: review.quality_report,
  guidance: "The quality service returned an action this workflow does not handle. Treat the run as unverified and inspect the service response.",
}}];

// An unbounded rework loop searches until something passes, which is a
// different thing from getting it right. Two recompiles, then a person looks.
const j = $json;
return [{json:{
  status: 'rework_budget_exhausted',
  production_published: false,
  reworks_attempted: Math.max(0, Number(j.rework_round || 0) - 1),
  action: j.action,
  detail: j.detail,
  focus: j.focus || [],
  findings_so_far: j.prior_findings || [],
  metrics: j.metrics,
  coverage: j.coverage,
  quality_report: j.quality_report,
}}];

// Four rounds without the picture changing is not a sampling problem. What is
// left is a judgement about specific cases, which is what the branch is named
// after.
const j = $json;
return [{json:{
  status: 'case_review_required',
  production_published: false,
  rounds_sampled: Number(j.round_index || 0),
  working_pool_remaining: j.working_pool_remaining,
  action: j.action,
  detail: j.detail,
  focus: j.focus || [],
  metrics: j.metrics,
  coverage: j.coverage,
  quality_report: j.quality_report,
}}];
